$urls = @(
    "https://www.jaimeibrahim.com/work/opera-video",
    "https://www.jaimeibrahim.com/work/project-five-748cx-egbkj",
    "https://www.jaimeibrahim.com/work/glgexplainer"
)

$siteChrome = @("site+header", "site+footer", "jaimeibrahim_stacked")

foreach ($url in $urls) {
    Write-Host "`n=========================================="
    Write-Host "PAGE: $url"
    Write-Host "==========================================`n"

    try {
        $response = Invoke-WebRequest -Uri $url -UseBasicParsing -TimeoutSec 30
        $html = $response.Content

        # Extract all squarespace-cdn image URLs
        $pattern = 'images\.squarespace-cdn\.com/content/v1/[^\s"''<>)}\]]+'
        $matches = [regex]::Matches($html, $pattern)

        $uniqueUrls = @{}
        foreach ($m in $matches) {
            $val = $m.Value
            # Skip site chrome
            $isChrome = $false
            foreach ($chrome in $siteChrome) {
                if ($val -like "*$chrome*") {
                    $isChrome = $true
                    break
                }
            }
            if (-not $isChrome) {
                $uniqueUrls[$val] = $true
            }
        }

        if ($uniqueUrls.Count -eq 0) {
            Write-Host "  NO PROJECT CONTENT IMAGES FOUND (only site chrome)"
            Write-Host "  Total squarespace-cdn matches (including chrome): $($matches.Count)"
        } else {
            Write-Host "  Content images found: $($uniqueUrls.Count)"
            $i = 1
            foreach ($imgUrl in ($uniqueUrls.Keys | Sort-Object)) {
                Write-Host "  [$i] https://$imgUrl"
                $i++
            }
        }

        # Also check for Vimeo/YouTube embeds
        $vimeoPattern = 'vimeo\.com/[^\s"''<>)}\]]+|player\.vimeo\.com/[^\s"''<>)}\]]+'
        $vimeoMatches = [regex]::Matches($html, $vimeoPattern)
        if ($vimeoMatches.Count -gt 0) {
            Write-Host "`n  Vimeo URLs found:"
            $vimeoMatches | ForEach-Object { Write-Host "    $($_.Value)" } | Sort-Object -Unique
        }

        $ytPattern = 'youtube\.com/[^\s"''<>)}\]]+|youtu\.be/[^\s"''<>)}\]]+'
        $ytMatches = [regex]::Matches($html, $ytPattern)
        if ($ytMatches.Count -gt 0) {
            Write-Host "`n  YouTube URLs found:"
            $ytMatches | ForEach-Object { Write-Host "    $($_.Value)" } | Sort-Object -Unique
        }

        # Check for any video block IDs or embed blocks
        $videoBlockPattern = 'video|embed|iframe|\.mp4|\.mov'
        $videoRefs = [regex]::Matches($html, $videoBlockPattern)
        Write-Host "`n  Video-related keyword occurrences: $($videoRefs.Count)"

        # Look for Squarespace native video references
        $nativeVideoPattern = 'sqsp-video|sqs-video|data-video|video-block'
        $nativeVideoMatches = [regex]::Matches($html, $nativeVideoPattern)
        if ($nativeVideoMatches.Count -gt 0) {
            Write-Host "  Native Squarespace video refs: $($nativeVideoMatches.Count)"
            $nativeVideoMatches | ForEach-Object { Write-Host "    $($_.Value)" }
        }

        # Dump a portion around any "assetUrl" or "contentType" references
        $assetPattern = 'assetUrl[^}]{0,200}'
        $assetMatches = [regex]::Matches($html, $assetPattern)
        if ($assetMatches.Count -gt 0) {
            Write-Host "`n  Asset URL references:"
            foreach ($am in $assetMatches) {
                Write-Host "    $($am.Value)"
            }
        }

        # Also look for static1.squarespace.com references (alternate CDN)
        $staticPattern = 'static1\.squarespace\.com/static/[^\s"''<>)}\]]+'
        $staticMatches = [regex]::Matches($html, $staticPattern)
        $staticUnique = @{}
        foreach ($sm in $staticMatches) {
            $val = $sm.Value
            $isChrome = $false
            foreach ($chrome in $siteChrome) {
                if ($val -like "*$chrome*") { $isChrome = $true; break }
            }
            if (-not $isChrome) { $staticUnique[$val] = $true }
        }
        if ($staticUnique.Count -gt 0) {
            Write-Host "`n  static1.squarespace.com content refs:"
            foreach ($su in ($staticUnique.Keys | Sort-Object)) {
                Write-Host "    https://$su"
            }
        }

    } catch {
        Write-Host "  ERROR fetching: $($_.Exception.Message)"
    }
}

$basePath = "G:\JAIME_IBRAHIM_2026_Website_Update\2026 Work"

$folders = @(
    "GLG_Brand_Work",
    "Bloomberg_Brand_Work",
    "Battle_Bank",
    "LRTF_Package_Design",
    "TYA_Event_Branding",
    "TIAA_Brand_Work",
    "Met_Opera",
    "Wealth_Product_Branding",
    "Summer_Picnic"
)

foreach ($folder in $folders) {
    $fullPath = Join-Path $basePath $folder
    Write-Host "`n=========================================="
    Write-Host "FOLDER: $folder"
    Write-Host "==========================================`n"

    if (Test-Path $fullPath) {
        $files = Get-ChildItem $fullPath -Recurse -File -ErrorAction SilentlyContinue
        foreach ($f in $files) {
            $rel = $f.FullName.Substring($fullPath.Length + 1)
            $sizeKB = [math]::Round($f.Length / 1024, 0)
            Write-Host "  $rel  (${sizeKB}KB)"
        }
        Write-Host "`n  Total files: $($files.Count)"
    } else {
        Write-Host "  FOLDER NOT FOUND"
    }
}

